					const positions = Float32Array.from(this._splatPositions);
					const vertexCount = this._vertexCount;
					this._worker.postMessage({
						command: GaussianSplattingSortWorkerCommand.POSITIONS,
						positions,
						vertexCount
					}, [positions.buffer]);
					this._postIntervalsToWorker();
